"user_need": "两人在无限流副本里是\"复活点绑定者\"（一人死另一人立刻读档），但他们彼此以为对方是NPC。男主是资深玩家，女主是第一次登录的新人。他带她通关七个副本，每次她死亡他都读档重来，直到第八次他发现她的ID旁标注着\"已注销玩家（三年前）\"——她早就死了，现在的她是他执念生成的幻觉。但他选择不揭穿，继续带她\"通关\"。3万字，Meta感。",
"inspiration_state": "clear_inspiration",
"extracted_elements": {
"emotion_verbs": ["执念", "守护", "假装", "复活", "通关"],
"scene_elements": ["无限流副本", "复活点绑定", "NPC", "幻觉", "读档", "系统面板", "好感度"],
"relationship_tension": ["彼此以为对方是NPC", "男主知道真相却不揭穿", "女主是已死玩家的意识碎片"],
"user_preferences": {
"desired_emotion": "甜爽、治愈、双向奔赴",
"forbidden": ["不要虐心", "不要女主消失", "不要男主黑化", "不要强行分离", "不要第三者"]
}
},
"selected_recipe": {
"x_axis_mode_id": "A2",
"x_axis_mode_name": "援救",
"y_axis_tags": ["无限流", "系统流"],
"reaction_strength": "↗",
"tension_stars":3,
"forbidden_elements": ["不要虐心误会", "不要女主真的消失", "不要男主黑化", "不要强行分离", "不要第三者"],
"x_axis_display": "男主作为资深玩家发现女主这个\"特殊NPC\"的异常，决定带她\"通关\"离开无限流。援救的对象从\"被困NPC\"逐渐变成\"被困玩家的意识碎片\"，最终目标是让她真正\"复活\"。",
"y_axis_combination_effect": "无限流提供副本挑战和通关目标，系统流提供好感度面板和任务系统作为金手指。两者结合让\"援救\"过程充满游戏感和养成乐趣，每次副本都是一次\"约会\"。",
"reaction_formula": "系统流的好感度机制为援救提供量化目标，无限流的副本轮回为感情升温提供场景，两者协同将\"拯救NPC\"转化为\"双向奔赴的恋爱养成\"。",
"platform_fit": ["晋江", "起点", "长佩"]
},
"one_sentence_synopsis": "资深玩家发现副本里的\"新人NPC\"竟是三年前已故玩家的意识碎片，他决定刷满好感度带她\"复活\"，却在通关路上和她双向奔赴。"
}
"}

