function.arguments:
 {"path": "characters.json", "content": "{
"main_characters": [
{
"name": "陆沉",
"role": "protagonist",
"identity": "无限流资深玩家，S级通关者，独行侠",
"traits": ["外冷内热", "责任感强", "毒舌心软", "观察力敏锐", "执念深重"],
"overt_motivation": "带这个\"新人NPC\"通关所有副本，刷满好感度让她\"复活\"",
"covert_motivation": "弥补三年前没能救下她的愧疚，这次绝不放手",
"secret_fear": "害怕再次失去她，害怕自己的执念只是自我感动",
"misperception_of_other": "以为她是系统生成的特殊NPC，不知道她是三年前已故玩家的意识碎片",
"hidden_connection": "三年前在\"亡灵列车\"副本中，她为救他而死，他亲眼看着她的ID变成灰色"
},
{
"name": "苏念",
"role": "deuteragonist",
"identity": "三年前已故玩家的意识碎片，被困在无限流中的\"特殊NPC\"",
"traits": ["乐观开朗", "有点迷糊", "关键时刻靠谱", "共情能力强", "隐藏的坚韧"],
"overt_motivation": "通关所有副本，离开这个奇怪的世界",
"covert_motivation": "找回自己丢失的记忆，弄清楚自己到底是谁",
"secret_fear": "害怕发现自己只是\"不存在的人\"，害怕自己的存在只是别人的执念",
"misperception_of_other": "以为陆沉是高级NPC，因为他总是能看到她看不到的\"系统面板\"",
"hidden_connection": "她的意识碎片中残留着对陆沉的模糊好感，但她以为那只是NPC的设定"
}
],
"supporting_characters": [
{
"name": "系统007",
"function": "助力",
"identity": "无限流主神系统的子程序",
"description": "负责发布任务、显示好感度面板、提供副本信息。偶尔会吐槽陆沉的执念太深。"
},
{
"name": "林野",
"function": "助力",
"identity": "陆沉的旧识，B级玩家",
"description": "知道陆沉三年前的事，偶尔出现提供信息或助攻，是两人关系的见证者。"
}
],
"relationship_dynamics": "两人都以为对方是NPC，在并肩作战中逐渐产生好感。陆沉用好感度面板量化自己的感情，苏念把陆沉的\"特殊待遇\"理解为NPC设定。直到第八次副本，真相揭开，两人从\"攻略NPC\"变成\"双向奔赴\"。"
}
"}

{"path": "outline.json", "content": "{
"act_one": {
"description": "建立无限流世界观，引入男女主。陆沉在副本中遇到\"新人NPC\"苏念，发现她的异常后决定带她通关。好感度系统出现，两人在并肩作战中产生好感，但都以为对方是NPC。",
"key_chapters": [
{
"chapter_number":1,
"chapter_title": "副本里的新人",
"core_event": "陆沉在\"废弃医院\"副本中遇到自称\"第一次登录\"的苏念，她对副本规则一无所知，却意外地乐观。陆沉本想独自通关，但系统提示\"检测到可绑定玩家\"。",
"emotional_tone": "轻松搞笑，带点悬疑",
"key_scenes": ["苏念在副本里迷路却意外发现隐藏道具", "陆沉吐槽\"这NPC智能有点高\"", "两人被困在同一个房间，苏念讲冷笑话缓解紧张"]
},
{
"chapter_number":2,
"chapter_title": "绑定与异常",
"core_event": "陆沉发现苏念的\"玩家面板\"是灰色的，系统显示\"特殊NPC-意识碎片\"。他决定带她通关，希望能找到让她\"复活\"的方法。好感度系统激活，当前好感度：5（陌生）。",
"emotional_tone": "悬疑+好奇",
"key_scenes": ["陆沉研究苏念的面板，发现异常标注", "系统007提示\"好感度可解锁特殊剧情\"", "苏念问陆沉为什么对她这么好，陆沉说\"NPC设定\""]
},
{
"chapter_number":3,
"chapter_title": "第一次通关",
"core_event": "两人配合通关\"废弃医院\"副本。苏念虽然是\"新人\"，但直觉敏锐，多次帮陆沉避开陷阱。通关后好感度升至30（友好）。陆沉开始怀疑她不只是NPC。",
"emotional_tone": "紧张刺激+甜",
"key_scenes": ["苏念替陆沉挡下致命一击，陆沉震惊", "通关后的结算界面，苏念好奇地看着自己的\"数据\"", "陆沉给苏念\"喂\"恢复道具，苏念说\"NPC不需要这个吧\""]
},
{
"chapter_number":4,
"chapter_title": "休息站的日常",
"core_event": "副本间隙，两人在\"休息站\"相处。苏念问陆沉很多关于\"外面世界\"的问题，陆沉发现她对三年前的事完全没有记忆。好感度升至50（信赖）。",
"emotional_tone": "温馨日常，暗流涌动",
"key_scenes": ["苏念在休息站\"逛街\"，对一切都好奇", "陆沉教苏念使用系统面板，苏念学得很快", "苏念说\"和你在一起很安心\"，陆沉心跳加速"]
},
{
"chapter_number":5,
"chapter_title": "死亡与读档",
"core_event": "第二个副本\"亡灵列车\"，苏念在关键时刻死亡。陆沉触发\"复活点绑定\"机制，读档重来。他发现自己对苏念的死有异常强烈的情绪波动。好感度：55（在意）。",
"emotional_tone": "紧张+心痛",
"key_scenes": ["苏念为救陆沉被怪物击中，陆沉瞳孔骤缩", "读档后陆沉沉默很久，系统提示\"检测到玩家情绪异常\"", "陆沉对苏念说\"下次别这么傻了\"，苏念笑着说\"NPC设定就是要保护玩家啊\""]
}
],
"turning_point": "陆沉在查看苏念的详细信息时，发现她的ID旁有一行灰色小字：\"状态：已注销（三年前）\"。他选择暂时不告诉她。"
},
"act_two": {
"description": "两人继续通关副本，感情不断升温。苏念开始怀疑自己的身份，陆沉在\"要不要告诉她真相\"之间挣扎。林野出现，透露三年前的往事。第七个副本，苏念再次死亡，陆沉第八次读档，真相彻底揭开。",
"key_chapters": [
{
"chapter_number":6,
"chapter_title": "第三个副本",
"core_event": "\"镜像迷宫\"副本，两人需要配合才能找到出口。苏念的直觉再次发挥作用，好感度升至65（心动）。陆沉开始用\"NPC需要升级\"的借口给苏念买道具。",
"emotional_tone": "甜+烧脑",
"key_scenes": ["苏念在迷宫中\"感应\"到正确方向，陆沉惊讶", "两人被困在镜像中，苏念说\"不管哪个是真的你，我都相信\"", "通关后陆沉偷偷给苏念买了\"限定皮肤\""]
},
{
"chapter_number":7,
"chapter_title": "第四个副本",
"core_event": "\"深海遗迹\"副本，水下作战。苏念差点溺水，陆沉紧紧抓住她的手。好感度升至75（喜欢）。苏念问陆沉：\"你为什么对我这么好？\"陆沉说：\"因为你是特别的NPC。\"",
"emotional_tone": "紧张+暧昧",
"key_scenes": ["水下苏念无法呼吸，陆沉把氧气分给她", "苏念靠在陆沉怀里，听到他的心跳", "陆沉说\"特别的NPC\"时，苏念眼中闪过一丝失落"]
},
{
"chapter_number":8,
"chapter_title": "第五个副本",
"core_event": "\"末日废土\"副本，两人扮演幸存者。苏念展现出惊人的适应力，好感度升至82（爱慕）。陆沉发现自己越来越难以把她当作NPC。",
"emotional_tone": "热血+甜",
"key_scenes": ["苏念用\"NPC技能\"帮陆沉解决危机，陆沉怀疑她的能力来源", "夜晚两人靠在一起看星星，苏念说\"如果能一直这样就好了\"", "陆沉在心里说\"会的，我会让你一直存在\""]
},
{
"chapter_number":9,
"chapter_title": "旧识来访",
"core_event": "林野出现，告诉陆沉三年前\"亡灵列车\"副本的真相：苏念是为了救他而死的。陆沉的执念正是从那时开始。林野问：\"你打算告诉她吗？\"陆沉沉默。",
"emotional_tone": "沉重+回忆",
"key_scenes": ["林野展示三年前的副本记录，苏念的ID在最后一刻变成灰色", "陆沉看着记录，手在发抖", "林野说\"她的意识碎片还在，你的执念让她\"活\"了下来\""]
},
{
"chapter_number":10,
"chapter_title": "第六个副本",
"core_event": "\"幽灵古堡\"副本，苏念开始做奇怪的梦，梦中有一个模糊的身影。她问陆沉：\"我是不是忘记了什么？\"陆沉说：\"NPC不会有记忆的。\"好感度：85（深爱）。",
"emotional_tone": "悬疑+虐心",
"key_scenes": ["苏念在梦中看到陆沉的脸，醒来后心跳加速", "陆沉回避苏念的问题，系统提示\"玩家说谎，好感度-2\"", "苏念说\"不管我是谁，我都想和你在一起\""]
},
{
"chapter_number":11,
"chapter_title": "身份的疑问",
"core_event": "苏念发现自己的\"玩家面板\"和其他NPC不同，她开始怀疑自己的身份。陆沉用各种借口搪塞，但苏念越来越不安。好感度：88（深爱+不安）。",
"emotional_tone": "紧张+疑惑",
"key_scenes": ["苏念偷偷查看自己的面板，发现\"意识碎片\"的标注", "苏念问陆沉\"意识碎片是什么意思\"，陆沉沉默", "苏念说\"你是不是有什么事瞒着我\""]
},
{
